def solution(paragraphs, aligns, width):
    out = ['*' * (width + 2)]
    for para, align in zip(paragraphs, aligns):
        line = ''
        lines = []
        for w in para:
            if not line:
                line = w
            elif len(line) + 1 + len(w) <= width:
                line += ' ' + w
            else:
                lines.append(line)
                line = w
        if line:
            lines.append(line)
        for ln in lines:
            out.append('*' + (ln.ljust(width) if align == 'LEFT' else ln.rjust(width)) + '*')
    out.append('*' * (width + 2))
    return out
